<?php
declare(strict_types=1);
use App\Support\Database;
return static function(Database $db):void{
 $db->execute("CREATE TABLE IF NOT EXISTS wallets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,country_id BIGINT UNSIGNED NOT NULL,currency_code CHAR(3) NOT NULL,available_balance_minor BIGINT NOT NULL DEFAULT 0,reserved_balance_minor BIGINT NOT NULL DEFAULT 0,status ENUM('ACTIVE','FROZEN','CLOSED') NOT NULL DEFAULT 'ACTIVE',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL,UNIQUE KEY wallet_user(user_id),INDEX wallet_country_currency(country_id,currency_code),CONSTRAINT fk_wallet_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_wallet_country FOREIGN KEY(country_id) REFERENCES countries(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->execute("CREATE TABLE IF NOT EXISTS ledger_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,public_id CHAR(36) NOT NULL,reference VARCHAR(80) NOT NULL,user_id BIGINT UNSIGNED NOT NULL,wallet_id BIGINT UNSIGNED NOT NULL,country_id BIGINT UNSIGNED NOT NULL,currency_code CHAR(3) NOT NULL,transaction_type ENUM('DEPOSIT','INVESTMENT_PURCHASE','INVESTMENT_PRINCIPAL_RETURN','INVESTMENT_PROFIT','SHARE_SALE','WITHDRAWAL','WITHDRAWAL_FEE','DEPOSIT_FEE','ADMIN_CREDIT','ADMIN_DEBIT','REVERSAL','ADJUSTMENT','RESERVATION','RESERVATION_RELEASE') NOT NULL,direction ENUM('CREDIT','DEBIT') NOT NULL,amount_minor BIGINT UNSIGNED NOT NULL,fee_minor BIGINT UNSIGNED NOT NULL DEFAULT 0,balance_before_minor BIGINT NOT NULL,balance_after_minor BIGINT NOT NULL,status ENUM('PENDING','COMPLETED','FAILED','REVERSED','CANCELLED') NOT NULL DEFAULT 'COMPLETED',external_reference VARCHAR(190) NULL,related_entity_type VARCHAR(80) NULL,related_entity_id VARCHAR(80) NULL,description VARCHAR(500) NOT NULL,metadata JSON NULL,created_by_type VARCHAR(40) NOT NULL,created_by_id BIGINT UNSIGNED NULL,reversal_of_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY ledger_public(public_id),UNIQUE KEY ledger_reference(reference),UNIQUE KEY ledger_related(related_entity_type,related_entity_id,transaction_type),INDEX ledger_wallet_date(wallet_id,created_at),INDEX ledger_user_date(user_id,created_at),INDEX ledger_country_currency(country_id,currency_code),CONSTRAINT fk_ledger_wallet FOREIGN KEY(wallet_id) REFERENCES wallets(id) ON DELETE RESTRICT,CONSTRAINT fk_ledger_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_ledger_country FOREIGN KEY(country_id) REFERENCES countries(id) ON DELETE RESTRICT,CONSTRAINT fk_ledger_reversal FOREIGN KEY(reversal_of_id) REFERENCES ledger_transactions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->execute("CREATE TABLE IF NOT EXISTS wallet_reservations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,public_id CHAR(36) NOT NULL,wallet_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,amount_minor BIGINT UNSIGNED NOT NULL,status ENUM('ACTIVE','RELEASED','CONSUMED','CANCELLED') NOT NULL DEFAULT 'ACTIVE',purpose VARCHAR(80) NOT NULL,related_entity_type VARCHAR(80) NULL,related_entity_id VARCHAR(80) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,released_at DATETIME NULL,UNIQUE KEY reservation_public(public_id),INDEX reservation_wallet(wallet_id,status),CONSTRAINT fk_reservation_wallet FOREIGN KEY(wallet_id) REFERENCES wallets(id) ON DELETE RESTRICT,CONSTRAINT fk_reservation_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->execute("CREATE TABLE IF NOT EXISTS dynamic_forms (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,form_key VARCHAR(100) NOT NULL,purpose ENUM('DEPOSIT','WITHDRAWAL','KYC','GENERAL') NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL,UNIQUE KEY form_key(form_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->execute("CREATE TABLE IF NOT EXISTS dynamic_form_fields (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,form_id BIGINT UNSIGNED NOT NULL,field_key VARCHAR(100) NOT NULL,field_type ENUM('TEXT','NUMBER','EMAIL','PHONE','TEXTAREA','SELECT','MULTI_SELECT','RADIO','CHECKBOX','DATE','FILE','COPYABLE_VALUE','INSTRUCTION','HIDDEN') NOT NULL,label VARCHAR(255) NOT NULL,placeholder VARCHAR(255) NULL,help_text TEXT NULL,default_value TEXT NULL,validation_rules JSON NULL,min_value VARCHAR(50) NULL,max_value VARCHAR(50) NULL,accepted_mimes JSON NULL,max_file_size BIGINT UNSIGNED NULL,is_required TINYINT(1) NOT NULL DEFAULT 0,is_user_editable TINYINT(1) NOT NULL DEFAULT 1,is_visible TINYINT(1) NOT NULL DEFAULT 1,sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL,UNIQUE KEY form_field_key(form_id,field_key),INDEX form_fields(form_id,sort_order),CONSTRAINT fk_form_field_form FOREIGN KEY(form_id) REFERENCES dynamic_forms(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->execute("CREATE TABLE IF NOT EXISTS dynamic_form_field_options (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,field_id BIGINT UNSIGNED NOT NULL,option_value VARCHAR(190) NOT NULL,option_label VARCHAR(255) NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0,UNIQUE KEY field_option_value(field_id,option_value),CONSTRAINT fk_form_option_field FOREIGN KEY(field_id) REFERENCES dynamic_form_fields(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->execute("CREATE TABLE IF NOT EXISTS deposit_methods (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,public_id CHAR(36) NOT NULL,name VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL,description TEXT NULL,instructions TEXT NULL,icon_path VARCHAR(255) NULL,enabled TINYINT(1) NOT NULL DEFAULT 0,minimum_amount_minor BIGINT UNSIGNED NOT NULL,maximum_amount_minor BIGINT UNSIGNED NULL,fee_type ENUM('NONE','FIXED','PERCENTAGE') NOT NULL DEFAULT 'NONE',fee_value DECIMAL(20,8) NOT NULL DEFAULT 0,fee_behavior ENUM('DEDUCT_FROM_CREDIT','ADD_TO_REQUIRED_PAYMENT') NOT NULL DEFAULT 'DEDUCT_FROM_CREDIT',estimated_processing_time VARCHAR(190) NULL,form_id BIGINT UNSIGNED NULL,sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL,UNIQUE KEY deposit_method_public(public_id),UNIQUE KEY deposit_method_slug(slug),CONSTRAINT fk_deposit_method_form FOREIGN KEY(form_id) REFERENCES dynamic_forms(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->execute("CREATE TABLE IF NOT EXISTS deposit_method_countries (deposit_method_id BIGINT UNSIGNED NOT NULL,country_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(deposit_method_id,country_id),CONSTRAINT fk_dmc_method FOREIGN KEY(deposit_method_id) REFERENCES deposit_methods(id) ON DELETE RESTRICT,CONSTRAINT fk_dmc_country FOREIGN KEY(country_id) REFERENCES countries(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->execute("CREATE TABLE IF NOT EXISTS deposit_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,public_id CHAR(36) NOT NULL,reference VARCHAR(80) NOT NULL,user_id BIGINT UNSIGNED NOT NULL,wallet_id BIGINT UNSIGNED NOT NULL,country_id BIGINT UNSIGNED NOT NULL,currency_code CHAR(3) NOT NULL,deposit_method_id BIGINT UNSIGNED NOT NULL,method_snapshot JSON NOT NULL,requested_amount_minor BIGINT UNSIGNED NOT NULL,fee_minor BIGINT UNSIGNED NOT NULL DEFAULT 0,expected_credit_minor BIGINT UNSIGNED NOT NULL,status ENUM('PENDING','UNDER_REVIEW','APPROVED','REJECTED','CANCELLED') NOT NULL DEFAULT 'PENDING',submitted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed_at DATETIME NULL,reviewed_by_user_id BIGINT UNSIGNED NULL,rejection_reason TEXT NULL,admin_notes TEXT NULL,approved_ledger_transaction_id BIGINT UNSIGNED NULL,cancelled_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL,UNIQUE KEY deposit_public(public_id),UNIQUE KEY deposit_reference(reference),UNIQUE KEY deposit_ledger(approved_ledger_transaction_id),INDEX deposit_queue(status,country_id,submitted_at),INDEX deposit_user(user_id,submitted_at),CONSTRAINT fk_deposit_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_deposit_wallet FOREIGN KEY(wallet_id) REFERENCES wallets(id) ON DELETE RESTRICT,CONSTRAINT fk_deposit_country FOREIGN KEY(country_id) REFERENCES countries(id) ON DELETE RESTRICT,CONSTRAINT fk_deposit_method FOREIGN KEY(deposit_method_id) REFERENCES deposit_methods(id) ON DELETE RESTRICT,CONSTRAINT fk_deposit_reviewer FOREIGN KEY(reviewed_by_user_id) REFERENCES users(id) ON DELETE SET NULL,CONSTRAINT fk_deposit_ledger FOREIGN KEY(approved_ledger_transaction_id) REFERENCES ledger_transactions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->execute("CREATE TABLE IF NOT EXISTS deposit_submission_values (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,deposit_request_id BIGINT UNSIGNED NOT NULL,field_key VARCHAR(100) NOT NULL,field_label VARCHAR(255) NOT NULL,value_text TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY deposit_field(deposit_request_id,field_key),CONSTRAINT fk_deposit_value_request FOREIGN KEY(deposit_request_id) REFERENCES deposit_requests(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->execute("CREATE TABLE IF NOT EXISTS deposit_files (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,deposit_request_id BIGINT UNSIGNED NOT NULL,field_key VARCHAR(100) NOT NULL,storage_path VARCHAR(255) NOT NULL,original_filename VARCHAR(255) NOT NULL,mime_type VARCHAR(100) NOT NULL,file_size BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX deposit_files_request(deposit_request_id),CONSTRAINT fk_deposit_file_request FOREIGN KEY(deposit_request_id) REFERENCES deposit_requests(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
};
